"""RoboLab mustard placement, using only the public camera/proprioception client.
Interactive JSON commands are archived alongside every observation and action.
"""
import sys, json, pathlib, traceback
import numpy as np
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot
ROOT = pathlib.Path('/app/output')
r = Robot()
spec = r.spec()
(ROOT/'spec.json').write_text(json.dumps(spec, indent=2))
print('SPEC', json.dumps(spec), flush=True)
seq = 0

def save(res, label):
    global seq
    dest = ROOT / f'{seq:03d}_{label}'
    seq += 1
    res.save(str(dest))
    print('RESULT', str(dest), json.dumps(res.meta), flush=True)
    return res

obs = save(r.get_obs(depth=True), 'initial')
print('READY', flush=True)
for line in sys.stdin:
    try:
        cmd = json.loads(line)
        with (ROOT/'commands.jsonl').open('a') as f: f.write(json.dumps(cmd)+'\n')
        op = cmd.pop('op')
        if op == 'observe': obs = save(r.get_obs(**cmd), 'observe')
        elif op == 'submit': obs = save(r.submit(**cmd), 'action')
        elif op == 'ik': print('IK', json.dumps(r.ik(**cmd)), flush=True)
        elif op == 'fk': print('FK', json.dumps(r.fk(**cmd)), flush=True)
        elif op == 'status': print('STATUS', json.dumps(r.status()), flush=True)
        elif op == 'recover':
            r.wait_ready()
            print('STATUS', json.dumps(r.status()), flush=True)
        else: print('Unknown command', op, flush=True)
    except Exception:
        traceback.print_exc()
    print('READY', flush=True)
